// Common operations (x86-64 thread local storage base)

// Base address to set
unsigned long fs_base = 0xFEEDCAFE0000ULL;

// Set FS register base address
arch_prctl(ARCH_SET_FS, fs_base);

// Variable to store retrieved base address
unsigned long current_fs_base;

// Retrieve current FS register base address
arch_prctl(ARCH_GET_FS, &current_fs_base);

// Other codes: ARCH_SET_GS, ARCH_GET_GS,
// ARCH_SET_CPUID, ARCH_MAP_VDSO_BASE
